import{_ as i,l as n,o as a,c as s,v as r,p as l,x as t,d as u,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"效用函数何时存在","description":"","frontmatter":{"title":"效用函数何时存在","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/utility-representation.md","filePath":"econ/utility-representation.md","lastUpdated":1789023840000}'),m={name:"econ/utility-representation.md"};function h(E,e,d,B,b,_){const o=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="效用函数何时存在" tabindex="-1">效用函数何时存在 <a class="header-anchor" href="#效用函数何时存在" aria-label="Permalink to &quot;效用函数何时存在&quot;">​</a></h1><div class="epigraph"><p>一个连续的效用函数表示一个连续的偏好；反过来，连续偏好在适当的消费集上总可以被连续函数表示。</p><footer>—— 据 Debreu, Representation of a preference ordering by a numerical function, 1954；Theory of Value, 1959 整理</footer></div><p><a href="/econ/convex-preference">上一课</a>（凸偏好）。在此之上，理性偏好钉死：完备加传递，有限菜单上最大元非空。本课不重讲这两条公理，也不从「幸福」另起炉灶。缺口是：排序还只是二元关系，后课的预算最大化、斯勒茨基分解都要在实函数上做微分。何时存在 \\(u:X\\to\\mathbb{R}\\)，使 \\(u(x)\\ge u(y)\\) 当且仅当 \\(x\\succsim y\\)？后课默认已经读完本课，见到 \\(u\\) 就把它读成这个表示，而不是心理强度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限集上，理性本身就够。把最大元标成 \\(n\\)，次大标成 \\(n-1\\)，一直标下去，得到的是序数效用：任何严格递增变换 \\(f\\circ u\\) 表示同一套 \\(\\succsim\\)。缺口出在消费理论真正用的 \\(X\\subseteq\\mathbb{R}_+^n\\)。这里菜单可以是闭集、无界集，最大元可能不存在；即便存在，也不保证能用<strong>连续</strong>函数把整条关系写下来。不连续的表示会让后课的需求对应在价格上跳来跳去，包络定理没有对象。</p><p>因此本课要加的不是新的「喜欢」，而是拓扑条件：偏好在 \\(X\\) 的序拓扑里连续——上优集 \\(\\{y:y\\succsim x\\}\\) 与下优集 \\(\\{y:x\\succsim y\\}\\) 都闭。Debreu 的表示定理说：在连通的消费集上，连续的理性偏好有连续效用表示。单调与凸已经在上一课之前钉过；本课用它们只是为了后课的内部解更稳，不是再引入公理。</p><h3 id="表示是序数的-数字没有基数含义" tabindex="-1">表示是序数的，数字没有基数含义 <a class="header-anchor" href="#表示是序数的-数字没有基数含义" aria-label="Permalink to &quot;表示是序数的，数字没有基数含义&quot;">​</a></h3><p>\\(u(x)=2\\)、\\(u(y)=1\\) 只说 \\(x\\) 至少与 \\(y\\) 一样好，不说「好一倍」。后课写 \\(\\max u(x)\\) 时，一阶条件里的 \\(\\nabla u\\) 会随单调变换改尺度，但切点本身不变。人际比较同样读不出来：两个人的 \\(u\\) 不能相加。那是<a href="/econ/welfare-theorems">福利定理</a>另引进的公理，不是本课的副产品。</p><p><span class="marginnote">无差异曲线是 \\(u\\) 的水平集。有了连续 \\(u\\)，才谈得上「曲线」。上一课只有无差异关系，没有拓扑，画不出图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取 \\(X\\subseteq\\mathbb{R}_+^n\\) 连通（常用凸锥或非负象限）。理性且连续的 \\(\\succsim\\) 对应某个连续 \\(u\\)。构造不必唯一：Debreu 的证明用开区间去嵌偏好的分划；教科书里更常见的是沿一条严格单调路径取「刚好无差异」的标量。本课不把证明展开成习题，只锁定三件事：存在、连续、序数。</p><p>有了 \\(u\\)，菜单 \\(B\\) 上的最大元改写成 \\(\\arg\\max_{x\\in B}u(x)\\)。有限 \\(B\\) 上这与上一课的最大元相同；闭有界 \\(B\\) 上 Weierstrass 保证非空。预算集是后课才引进的特殊 \\(B\\)，本课不写价格。</p>',12)),(a(),l(p,null,{default:t(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E7%90%86%E6%80%A7%E5%81%8F%E5%A5%BD%20%E2%89%BD%22%5D%20--%3E%20C%5B%22%E8%BF%9E%E7%BB%AD%E6%80%A7%EF%BC%9A%E4%B8%8A%E4%B8%8B%E4%BC%98%E9%9B%86%E4%B8%BA%E9%97%AD%22%5D%0A%20%20C%20--%3E%20U%5B%22%E8%BF%9E%E7%BB%AD%E6%95%88%E7%94%A8%E8%A1%A8%E7%A4%BA%20u%22%5D%0A%20%20U%20--%3E%20M%5B%22argmax%20u%20%E4%BA%8E%E8%8F%9C%E5%8D%95%20B%22%5D%0A%20%20M%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%A2%84%E7%AE%97%E4%B8%8E%E9%A9%AC%E6%AD%87%E5%B0%94%E9%9C%80%E6%B1%82%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>凸性已经在<a href="/econ/convex-preference">凸偏好</a>进场。无差异集可以向原点弯；表示定理本身不管这个，但后课严格凸才让马歇尔需求单值。单调性同样已经有了：它可以保证内部解，但不创造 \\(u\\)。可微更后：Debreu 只给连续函数，导数是为了写斯勒茨基才另加的光滑。</p><p>局部非餍足已在<a href="/econ/monotonicity-lns">单调与局部非饱和</a>钉过。本课只保证「排序能写成函数」；钱是否花完，是需求课拿去用的，不是表示定理的结论。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续性排除「无穷小跳跃」：若 \\(x^n\\to x\\) 且每一点都优于 \\(y\\)，极限不能突然劣于 \\(y\\)。这让无差异集把 \\(X\\) 分成整齐的层，效用沿着层递增。后课对价格求导，靠的就是这层结构可微或至少局部 Lipschitz——可微是额外光滑，不是表示定理的结论。</p><p>序数性意味着后课所有「效用差」的说法都要翻译回偏好。马歇尔需求在单调变换下不变，间接效用会变，但间接效用的最大化者不变。这就是为什么需求课可以随便选一个方便的 \\(u\\)（拟线性、Cobb–Douglas），只要它表示同一 \\(\\succsim\\)。</p><p><span class="marginnote">词典序是理性但不连续的标准反例：它没有连续效用表示。后课默认不把词典序当消费者。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>表示定理不给出唯一 \\(u\\)，也不给出基数效用。期望效用课会再加独立性，那时仿射变换才被钉死——那是另一套公理，不是本课的加强。也不要把连续效用读成「人感觉平滑」：它是模型为了用分析工具付的拓扑代价。</p><p>实验里的不传递、不完备，上一课已经划成对照。本课在理性内部工作：若连续性也失败，后课的需求函数理论整段暂停。主干仍用 Debreu 表示，因为一般均衡的存在性证明要从连续需求出发。</p><p>拟凹、单调已经用来收紧需求形状，不是表示定理的前提。没有严格凸，\\(u\\) 仍可以存在，只是 \\(\\arg\\max\\) 可以是一整段无差异集。也不要把 Debreu 1954 的表示与 1959 年《价值理论》里的均衡存在混成一步：前者只把关系写成函数，后者才把函数送进市场。</p><p>后课默认：写 \\(u(x)\\) 就是在写一套连续理性偏好。预算、价格、收入，下一课才进入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有限集上理性即有序数效用；\\(\\mathbb{R}_+^n\\) 上还要连续性，才有连续表示。</li><li>\\(u\\) 不是偏好的替代物，是表示；严格递增变换表示同一 \\(\\succsim\\)。</li><li>菜单上的选择改写成 \\(\\arg\\max u\\)；预算尚未出现。</li><li>单调与凸已经在先修课；本课不加可微。</li><li>词典序是理性但不连续的反例；主干不把它当消费者。</li><li>出处：Debreu, <em>Theory of Value</em>；Mas-Colell, Whinston and Green, <em>Microeconomic Theory</em> 第 3 章；Varian, <em>Microeconomic Analysis</em>。</li></ul>',13))])}const x=i(m,[["render",h]]);export{f as __pageData,x as default};
